// 意图只提供原事业政策的明确选择，真实权限/资格与到场仍归本域统一预览。
#include "political_subordinate_appointment_authored.hpp"
namespace hanmo::resident {namespace {
Status matches(const PoliticalSubordinateAppointmentState& s,const PoliticsCatalog& politics,const PoliticalSubordinateAppointmentCatalog& appointments,const PoliticalSubordinateAppointmentIntentCatalog& catalog,const PoliticalSubordinateCareerPolicyRead& read,const PoliticalSubordinateAppointmentAuthoredOrigin& o,const StableId& actor,const PoliticalSubordinateAppointmentCommand& command){
 const auto fail=[&](){return common_failure("PoliticalSubordinateAuthoredOriginMismatch",o.intent_id);};const auto* i=catalog.intents.find(o.intent_id);const auto* p=i?appointments.policies.find(i->appointment_policy_id):nullptr;const auto* j=p?politics.jurisdictions.find(p->jurisdiction_id):nullptr;if(s.version!=1||catalog.version!=1||!i||!p||!j||actor!=o.actor_id||!read)return fail();
 return std::visit([&](const auto& cmd)->Status{using T=std::decay_t<decltype(cmd)>;
  if constexpr(std::is_same_v<T,PoliticalWithdrawSubordinateAppointment>)return common_failure("PoliticalSubordinateAuthoredWithdrawalUnsupported");
  else if constexpr(std::is_same_v<T,PoliticalOfferSubordinateAppointment>){const auto* career=read(i->issuer_director_policy_id);if(!career||o.stage!="offer"||!o.offer_fact_id.empty()||actor!=i->issuer_actor_id||o.director_policy_id!=i->issuer_director_policy_id||cmd.authority.actor_id!=actor||cmd.policy_id!=p->id||cmd.candidate_actor_id!=i->candidate_actor_id)return fail();bool permitted=false;for(const auto& post:career->staffing_posts)if(post.issuing_office_id==cmd.authority.office_id&&post.jurisdiction_id==j->id&&post.appointment_policy_id==p->appointment_policy_id&&std::find(post.candidate_actor_ids.begin(),post.candidate_actor_ids.end(),i->candidate_actor_id)!=post.candidate_actor_ids.end())permitted=true;return permitted?common_success():fail();}
  else {const PoliticalSubordinateAppointmentOffer* offer=nullptr;if constexpr(std::is_same_v<T,PoliticalAnswerSubordinateAppointment>)offer=s.offers.find(cmd.offer_fact_id);else{const auto* a=s.answers.find(cmd.acceptance_fact_id);offer=a&&a->accepted?s.offers.find(a->offer_fact_id):nullptr;}const auto* career=read(i->candidate_director_policy_id);if(!offer||!career||actor!=i->candidate_actor_id||offer->issuer_actor_id!=i->issuer_actor_id||offer->candidate_actor_id!=actor||offer->policy_id!=p->id||o.director_policy_id!=i->candidate_director_policy_id||o.offer_fact_id!=offer->id)return fail();auto response=read_political_subordinate_career_response(*career,offer->organization_id,j->id);if(!response.ok)return {false,{},response.error};if constexpr(std::is_same_v<T,PoliticalAnswerSubordinateAppointment>)return o.stage=="answer"&&response.value==cmd.accept?common_success():fail();else return o.stage=="arrival"&&response.value?common_success():fail();}
 },command);
}
}
Status validate_political_subordinate_authored_command(const CommonStore& c,const PoliticalSubordinateAppointmentState& s,const PoliticsCatalog& p,const PoliticalSubordinateAppointmentCatalog& a,const PoliticalSubordinateAppointmentIntentCatalog& i,const PoliticalSubordinateCareerPolicyRead& read,const PoliticalSubordinateAppointmentAuthoredOrigin& o,const StableId& actor,const PoliticalSubordinateAppointmentCommand& command){if(actor==c.state().metadata.player_actor_id)return common_failure("PoliticalSubordinateAuthoredNonPlayerRequired",actor);return matches(s,p,a,i,read,o,actor,command);}
Status validate_political_subordinate_authored_source(const CommonStore& c,const PoliticalSubordinateAppointmentState& s,const PoliticsCatalog& politics,const PoliticalSubordinateAppointmentCatalog& appointments,const PoliticalSubordinateAppointmentIntentCatalog& intents,const PoliticalSubordinateCareerPolicyRead& read,const StableId& id,const PoliticalSuccessionPlayerRead& player){
 const auto fail=[&](){return common_failure("PoliticalSubordinateAuthoredSourceRequired",id);};const auto* origin=s.authored_origins.find(id);const auto* head=c.state().facts.find(id);if(!origin||!head||!political_subordinate_appointment_fact_sequence(c,id)||!player)return fail();StableId actor;Integer tick=-1;PoliticalSubordinateAppointmentCommand command;
 if(const auto* o=s.offers.find(id)){if(o->id!=id||o->player_receipt||head->kind!="political_subordinate_appointment_offered")return fail();actor=o->issuer_actor_id;tick=o->tick;command=PoliticalOfferSubordinateAppointment{{o->organization_id,o->head_office_id,o->head_epoch,actor},o->policy_id,o->candidate_actor_id,o->target_epoch,o->jurisdiction_revision};}
 else if(const auto* a=s.answers.find(id)){if(a->id!=id||a->player_receipt||head->kind!=(a->accepted?"political_subordinate_appointment_accepted":"political_subordinate_appointment_declined"))return fail();actor=a->actor_id;tick=a->tick;command=PoliticalAnswerSubordinateAppointment{a->offer_fact_id,a->accepted};}
 else if(const auto* a=s.arrivals.find(id)){const auto* accepted=s.answers.find(a->acceptance_fact_id);const auto* o=accepted?s.offers.find(accepted->offer_fact_id):nullptr;if(!o||a->id!=id||a->player_receipt||head->kind!="political_subordinate_appointment_arrived")return fail();actor=a->actor_id;tick=a->tick;command=PoliticalArriveSubordinateAppointment{a->acceptance_fact_id,o->target_epoch};}
 else return fail();auto valid=matches(s,politics,appointments,intents,read,*origin,actor,command);if(!valid.ok)return valid;auto who=player(tick,id);if(!who.ok)return {false,{},who.error};return !who.value.empty()&&c.actor(who.value)&&c.actor(actor)&&who.value!=actor?common_success():common_failure("PoliticalSubordinateHistoricalNonPlayerRequired",id);
}
}
